-- Таблица 3 (Apache Derby): все страны; для каждой страны 5 строк (2020-2024);
-- колонки: ГОД, ВСЕГО, и суммы по 10 группам FAO (широкая форма, "транспонирование" через CASE-агрегацию)
SELECT * FROM (
  SELECT CAST(c.NAME_EN AS VARCHAR(80)) AS COUNTRY, y.YR AS "YEAR",
         CAST(SUM(CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END) AS DECIMAL(18,0)) AS "ВСЕГО",
         CAST(SUM(CASE WHEN g.CODE='1'  THEN CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END ELSE 0 END) AS DECIMAL(18,0)) AS "Группа 1",
         CAST(SUM(CASE WHEN g.CODE='2'  THEN CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END ELSE 0 END) AS DECIMAL(18,0)) AS "Группа 2",
         CAST(SUM(CASE WHEN g.CODE='3'  THEN CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END ELSE 0 END) AS DECIMAL(18,0)) AS "Группа 3",
         CAST(SUM(CASE WHEN g.CODE='4'  THEN CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END ELSE 0 END) AS DECIMAL(18,0)) AS "Группа 4",
         CAST(SUM(CASE WHEN g.CODE='5'  THEN CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END ELSE 0 END) AS DECIMAL(18,0)) AS "Группа 5",
         CAST(SUM(CASE WHEN g.CODE='6'  THEN CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END ELSE 0 END) AS DECIMAL(18,0)) AS "Группа 6",
         CAST(SUM(CASE WHEN g.CODE='7'  THEN CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END ELSE 0 END) AS DECIMAL(18,0)) AS "Группа 7",
         CAST(SUM(CASE WHEN g.CODE='8'  THEN CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END ELSE 0 END) AS DECIMAL(18,0)) AS "Группа 8",
         CAST(SUM(CASE WHEN g.CODE='9'  THEN CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END ELSE 0 END) AS DECIMAL(18,0)) AS "Группа 9",
         CAST(SUM(CASE WHEN g.CODE='A' THEN CASE y.YR WHEN 2020 THEN COALESCE(t.VALUE_Y2020,0) WHEN 2021 THEN COALESCE(t.VALUE_Y2021,0) WHEN 2022 THEN COALESCE(t.VALUE_Y2022,0) WHEN 2023 THEN COALESCE(t.VALUE_Y2023,0) WHEN 2024 THEN COALESCE(t.VALUE_Y2024,0) END ELSE 0 END) AS DECIMAL(18,0)) AS "Группа 10"
  FROM FISHSTAT.TSD_TRADE_PP_QUANTITY t
  JOIN FISHSTAT.REF_COUNTRY c ON CAST(c.UN_CODE AS VARCHAR(3)) = CAST(t.COUNTRY AS VARCHAR(3))
  JOIN (FISHSTAT.REL_COMMODITY_MAJOR r
        JOIN FISHSTAT.REF_COMMODITY_MAJOR2 g ON CAST(g.ID AS VARCHAR(20)) = CAST(r.PARENT_ID AS VARCHAR(20))
        JOIN FISHSTAT.REF_COMMODITY cm       ON CAST(cm.ID AS VARCHAR(20)) = CAST(r.CHILD_ID AS VARCHAR(20)))
       ON CAST(cm.FAO_CODE AS VARCHAR(20)) = CAST(t.COMMODITY AS VARCHAR(20))
  CROSS JOIN (VALUES (2020),(2021),(2022),(2023),(2024)) y(YR)
  GROUP BY c.NAME_EN, y.YR
) z
ORDER BY COUNTRY, "YEAR"
